DROP TABLE IF EXISTS orgs;
DROP TABLE IF EXISTS apps;
DROP TABLE IF EXISTS roles;
DROP TABLE IF EXISTS screens;
CREATE TABLE orgs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      org_code TEXT UNIQUE NOT NULL,
      org_name TEXT NOT NULL,
      projects_path TEXT,
      status TEXT DEFAULT 'active',
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE apps (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      org_id INTEGER NOT NULL,
      app_code TEXT UNIQUE NOT NULL,
      app_name TEXT NOT NULL,
      platform TEXT,
      framework TEXT,
      repo_name TEXT,
      root_path TEXT,
      publish_url TEXT,
      api_url TEXT,
      logo_url TEXT,
      status TEXT DEFAULT 'active',
      created_at TEXT DEFAULT CURRENT_TIMESTAMP, default_layout_key TEXT, app_shell_type TEXT, theme_config_json TEXT, branding_json TEXT, default_locale TEXT DEFAULT 'en', supported_locales_json TEXT DEFAULT '["en"]', i18n_strategy TEXT DEFAULT 'arb', translation_file_path TEXT, active_language_count INTEGER DEFAULT 3,
      FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE CASCADE
    );
CREATE TABLE roles (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      org_id INTEGER NOT NULL,
      role_code TEXT UNIQUE NOT NULL,
      role_name TEXT NOT NULL,
      role_level INTEGER DEFAULT 1,
      status TEXT DEFAULT 'active', topbar_config_json TEXT, sidebar_config_json TEXT, default_dashboard_screen_code TEXT, allowed_menu_json TEXT, role_layout_key TEXT, navigation_style TEXT, preferred_locale TEXT DEFAULT 'en', allowed_locales_json TEXT DEFAULT '["en"]', show_language_switcher INTEGER DEFAULT 1, test_email TEXT, test_password_secret_ref TEXT, auth_test_status TEXT DEFAULT 'not_run', auth_last_error TEXT, auth_last_run_at TEXT, auth_screenshot_path TEXT, auth_video_path TEXT, test_user_seed_status TEXT DEFAULT 'not_seeded', test_user_id TEXT, test_login_verified INTEGER DEFAULT 0, test_login_last_status TEXT DEFAULT 'not_run', test_login_last_error TEXT, test_login_last_run_at TEXT, primary_app_code TEXT, primary_app_url TEXT, auth_redirect_url TEXT, post_login_route TEXT, test_password TEXT DEFAULT 'Test@12345',
      FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE CASCADE
    );
CREATE TABLE screens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    app_id INTEGER,
    role_id INTEGER,
    screen_code TEXT,
    screen_name TEXT,
    route_path TEXT,
    cypress_ready INTEGER,
    cypress_ready_status TEXT,
    screenshot_path TEXT,
    video_recording_path TEXT,
    when_tested TEXT,
    is_valid INTEGER,
    complexity_score INTEGER,
    estimated_loc INTEGER,
    maintainability_score INTEGER,
    user_remarks TEXT,
    user_remark_status TEXT,
    required_components_json TEXT,
    actual_components_json TEXT,
    actual_file_path TEXT,
    allowed_roles_text TEXT,
    supports_mobile INTEGER,
    supports_tablet INTEGER
);
